-- ─────────────────────────────────────────────────────────────
-- talk_sentences table
-- Run this in Supabase SQL Editor (Dashboard → SQL Editor → New query)
-- ─────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS talk_sentences (
  id            uuid        DEFAULT gen_random_uuid() PRIMARY KEY,
  topic_id      text        NOT NULL,
  topic_title   text        NOT NULL,
  topic_title_en text       NOT NULL,
  topic_emoji   text        NOT NULL,
  topic_color_class text    NOT NULL,
  topic_icon_bg text        NOT NULL,
  level         text        NOT NULL CHECK (level IN ('A1','A2','B1','B2')),
  english       text        NOT NULL,
  swedish       text        NOT NULL,
  sort_order    integer     DEFAULT 0,
  created_at    timestamptz DEFAULT now()
);

-- Public read (sentences are not user-specific)
ALTER TABLE talk_sentences ENABLE ROW LEVEL SECURITY;
CREATE POLICY "public read talk_sentences" ON talk_sentences FOR SELECT USING (true);

-- Index for fast topic+level queries
CREATE INDEX IF NOT EXISTS idx_talk_sentences_topic_level ON talk_sentences (topic_id, level);

